    const gridPowerForPlanningW = Math.max(n(core.grid_power) - ownWallboxGridW, 0);
    const maxTotalKw = Math.max((gridPhaseLimitW*3 - gridSafetyMarginW - gridPowerForPlanningW) / 1000, 0);
    function totalKw() { return candidates.reduce((sum,c)=>sum + (c.type==='wallbox' ? powerFromWallboxCurrent(c.current) : powerFromBatteryCurrent(c.current)), 0); }
    for (let guard=0; guard<50 && totalKw() > Math.min(maxKw, maxTotalKw); guard++) {
        const c = [...candidates].sort((a,b)=>b.priority-a.priority || a.need-b.need)[0];
        if (!c) break;
        if (c.type === 'battery' && c.current > batteryMinA) c.current -= 1;
        else if (c.type === 'wallbox') {
            const idx = wallboxSteps.indexOf(c.current);
            if (idx > 0) c.current = wallboxSteps[idx-1]; else break;
        } else break;
    }

    // GRID handoff:
    // NT okno nezačínáme spotřebovávat automaticky od začátku. Nejprve se využije
    // energie domácí baterie nad effective minimum + nastavitelná rezerva.
    // Síť se zapne při první z událostí:
    //  1) odhadovaná energie nad rezervou se vyčerpá,
    //  2) nastane nejpozdější čas, kdy se nákup ještě stihne do konce NT / odjezdu,
    //  3) SOC už je na handoff hranici.
    const handoffReserveSoc = clamp(n(s('input_number.ems_grid_handoff_reserve_soc'), 5), 0, 20);
    const handoffSafetyMinutes = clamp(n(s('input_number.ems_grid_handoff_safety_minutes'), 20), 0, 180);
    const handoffMinDrainW = clamp(n(s('input_number.ems_grid_handoff_min_drain_w'), 300), 100, 5000);
    const handoffSoc = clamp(n(core.effective_min_soc) + handoffReserveSoc, 0, 100);
    const batteryCapacityKwhLocal = Math.max(n(s('input_number.ems_battery_capacity_kwh'), 48), 1);
    const batteryUsableKwh = Math.max((n(core.battery_soc) - handoffSoc) * batteryCapacityKwhLocal / 100, 0);
    const batteryReserveReached = n(core.battery_soc) <= handoffSoc + 0.1;

    const houseKw = Math.max(n(core.house_power) / 1000, 0);
    const pvKw = Math.max(n(core.pv_power) / 1000, 0);
    const actualBatteryDrainKw = Math.max(-n(core.battery_power) / 1000, 0);
    const largestSolarWallboxKw = candidates
        .filter(c => c.type === 'wallbox')
        .reduce((mx, c) => Math.max(mx, powerFromWallboxCurrent(c.current)), 0);

    // Odhad je záměrně konzervativní: vezmi horší z aktuálního skutečného vybíjení
    // a očekávaného odběru domu + jednoho prioritního wallboxu minus FV.
    const estimatedPreGridDrainKw = Math.max(
        actualBatteryDrainKw,
        houseKw + largestSolarWallboxKw - pvKw,
        handoffMinDrainW / 1000
    );
    const batterySupportHours = batteryUsableKwh / Math.max(estimatedPreGridDrainKw, 0.1);
    const batteryHandoffEstimateTs = batteryReserveReached
        ? now
        : now + Math.round(batterySupportHours * 3600000);

    let planned = 0;
    for (const c of candidates) {
        const kw = c.type==='wallbox' ? powerFromWallboxCurrent(c.current) : powerFromBatteryCurrent(c.current);
        const runHours = Math.min(durationH, c.need / Math.max(kw, 0.01));
        const runMs = Math.ceil(runHours * 3600000);
        const safetyMs = handoffSafetyMinutes * 60000;

        // w.end_ts už je případně oříznutý odjezdem auta.
        const latestStartTs = Math.max(w.start_ts, w.end_ts - runMs - safetyMs);
        const estimatedBatteryStartTs = Math.max(w.start_ts, batteryHandoffEstimateTs);
        const selectedStartTs = Math.max(
            w.start_ts,
            Math.min(latestStartTs, estimatedBatteryStartTs)
        );
        const endTs = Math.min(selectedStartTs + runMs, w.end_ts);
        const active = loadActive({enabled:true,start_ts:selectedStartTs,end_ts:endTs}, now);

        let startReason = 'latest_required_start';
        if (batteryReserveReached) startReason = 'battery_handoff_soc_reached';
        else if (estimatedBatteryStartTs <= latestStartTs) startReason = 'battery_energy_estimate';

        loads[c.id] = {
            enabled: true,
            need_kwh: round1(c.need),
            current_a: Math.round(c.current),
            planned_kwh: round1(Math.min(c.need, kw * Math.max((endTs - selectedStartTs) / 3600000, 0))),
            active,
            priority: candidates.indexOf(c) + 1,
            start_ts: selectedStartTs,
            latest_start_ts: latestStartTs,
            battery_handoff_estimate_ts: batteryHandoffEstimateTs,
            end_ts: endTs,
            start: fmtTime(selectedStartTs),
            latest_start: fmtTime(latestStartTs),
            battery_handoff_estimate: fmtTime(batteryHandoffEstimateTs),
            end: fmtTime(endTs),
            start_reason: startReason,
            handoff_soc: round1(handoffSoc),
            battery_usable_kwh: round1(batteryUsableKwh),
            estimated_pre_grid_drain_kw: round1(estimatedPreGridDrainKw),
            full_window: selectedStartTs <= w.start_ts && endTs >= w.end_ts
        };
        planned += loads[c.id].planned_kwh;
    }
    const missing = Math.max(totalNeed - planned, 0);
    const summaryParts = [];
    for (const id of ['id3','id4','battery']) {
        const l=loads[id]; if (!l.enabled) continue;
        const label = id === 'battery' ? 'baterka' : id.toUpperCase();
        summaryParts.push(`${label} ${l.current_a}A ${l.start}–${l.end} ${l.planned_kwh} kWh`);
    }
    return {
        mode:'hdo_spread', needed_kwh:round1(totalNeed), planned_kwh:round1(planned), missing_kwh:round1(missing), max_power_kw:maxKw,
        deadline_ts:deadlineTs, deadline:deadlineTs?fmtTime(deadlineTs):null,
        start_ts:w.start_ts, end_ts:w.end_ts, start:fmtTime(w.start_ts), end:fmtTime(w.end_ts), duration_h:round1(durationH),
        status: missing>0.1?'partial':'planned', summary: summaryParts.join(', ') || 'Není potřeba nic kupovat', loads,
        handoff: {
            reserve_soc: round1(handoffReserveSoc),
            handoff_soc: round1(handoffSoc),
            battery_usable_kwh: round1(batteryUsableKwh),
            battery_reserve_reached: batteryReserveReached,
            estimated_pre_grid_drain_kw: round1(estimatedPreGridDrainKw),
            estimated_support_hours: round1(batterySupportHours),
            battery_handoff_estimate_ts: batteryHandoffEstimateTs,
            battery_handoff_estimate: fmtTime(batteryHandoffEstimateTs),
            safety_minutes: handoffSafetyMinutes
        },
        slots:[{start_ts:w.start_ts,end_ts:w.end_ts,start:fmtTime(w.start_ts),end:fmtTime(w.end_ts),class:'cheap',discount:-10,label:'hdo_nt_spread',kwh:round1(planned)}]
    };
}

const batteryCapacity = n(s('input_number.ems_battery_capacity_kwh'), 32);
const hardMinSoc = n(s('input_number.ems_battery_hard_min_soc'), 40);
const id3Soc = n(s('sensor.auto_id4_sniffer_id3_soc_bms'));
const id4Soc = n(s('sensor.auto_id4_sniffer_id4_soc_bms'));
const id3Target = n(s('input_number.ems_id3_target_soc'), 50);
const id4Target = n(s('input_number.ems_id4_target_soc'), 50);
const id3ReqTo100 = n(s('sensor.auto_id4_sniffer_id_3_energie_do_100'));
const id4ReqTo100 = n(s('sensor.auto_id4_sniffer_id_4_energie_do_100'));
const id3Required = requiredToTarget(id3ReqTo100, id3Soc, id3Target);
const id4Required = requiredToTarget(id4ReqTo100, id4Soc, id4Target);

// Cíl auta je SOC cíl, ne minimální množství kWh.
// Původní >0.5 kWh práh způsoboval typické ukončení 80% cíle už na 79%.
const id3NeedsTarget = !!core.id3_connected && id3Soc < id3Target;
const id4NeedsTarget = !!core.id4_connected && id4Soc < id4Target;
// Když je energy-to-100 senzor na samém konci velmi malý / zaokrouhlený,
// necháme pro plánování alespoň symbolickou energii. Stav ON/OFF ale řídí SOC.
const id3NeedForPlanning = id3NeedsTarget ? Math.max(id3Required, 0.1) : 0;
const id4NeedForPlanning = id4NeedsTarget ? Math.max(id4Required, 0.1) : 0;

const id3DepartureRaw = parseDateTime('input_datetime.ems_id3_departure');
const id4DepartureRaw = parseDateTime('input_datetime.ems_id4_departure');
const id3UseDeparture = b('input_boolean.ems_id3_use_departure_time');
const id4UseDeparture = b('input_boolean.ems_id4_use_departure_time');
const departureBufferHours = n(s('input_number.ems_departure_buffer_hours'), 1);
const departureBufferMs = departureBufferHours * 3600000;
const id3Departure = id3DepartureRaw ? id3DepartureRaw - departureBufferMs : null;
const id4Departure = id4DepartureRaw ? id4DepartureRaw - departureBufferMs : null;
const batteryMissingSoc = Math.max(n(core.target_soc) - n(core.battery_soc), 0);
const batteryMissingKwh = batteryCapacity * batteryMissingSoc / 100;
const carRequiredTotal = id3NeedForPlanning + id4NeedForPlanning;
const connectedCarRequiredTotal = id3NeedForPlanning + id4NeedForPlanning;
const winter = !!core.ems_winter_mode;
const allowSolarLoads = !!core.ems_allow_solar_loads;
const allowGridCharge = !!core.ems_allow_grid_charge;
const bad = core.forecast_day_type_tomorrow === 'bad';
const normal = core.forecast_day_type_tomorrow === 'normal';
const sunny = core.forecast_day_type_tomorrow === 'sunny';
const wallboxMode = String(core.wallbox_mode || 'AUTO').toUpperCase();
const wallboxPriority = String(core.wallbox_priority || 'AUTO').toUpperCase();
const batteryGridMode = String(core.battery_grid_mode || 'AUTO').toUpperCase();
const totalMissingEnergy = batteryMissingKwh + connectedCarRequiredTotal;
let urgency = 'low'; if (totalMissingEnergy >= 25 || bad) urgency = 'high'; else if (totalMissingEnergy >= 10) urgency = 'normal';

let baseCarSolar = allowSolarLoads && core.battery_above_effective_min && core.any_car_connected && (sunny || (normal && !winter));
let allowCarSolar = false;
let allowCarGrid = false;
if (!core.ems_enabled || wallboxMode === 'OFF') { allowCarSolar=false; allowCarGrid=false; }
else if (wallboxMode === 'SOLAR') { allowCarSolar=baseCarSolar; allowCarGrid=false; }
else if (wallboxMode === 'GRID') { allowCarSolar=false; allowCarGrid=allowGridCharge && core.any_car_connected && connectedCarRequiredTotal>0.05 && core.cheap_grid_usable; }
else { allowCarSolar=baseCarSolar; }

const deadlineCars = [];
if (id3NeedsTarget && id3UseDeparture && id3Departure && id3Departure > now) {
    deadlineCars.push({ id:'id3', required_kwh:id3NeedForPlanning, connected:true, needs_target:true, use_departure:true, departure_ts:id3Departure });
}
if (id4NeedsTarget && id4UseDeparture && id4Departure && id4Departure > now) {
    deadlineCars.push({ id:'id4', required_kwh:id4NeedForPlanning, connected:true, needs_target:true, use_departure:true, departure_ts:id4Departure });
}
const connectedDeadlineCarRequired = deadlineCars.reduce((sum,c)=>sum+c.required_kwh, 0);
const earliestEffectiveDeadline = deadlineCars.length ? Math.min(...deadlineCars.map(c=>c.departure_ts)) : null;
const hoursToEarliestDeadline = earliestEffectiveDeadline ? (earliestEffectiveDeadline - now) / 3600000 : null;
const solarKwhBeforeDeadline = forecastKwhAvailableBeforeDeadline(earliestEffectiveDeadline);

const connectedNoDeadlineCarRequired =
    (id3NeedsTarget && !id3UseDeparture ? id3NeedForPlanning : 0) +
    (id4NeedsTarget && !id4UseDeparture ? id4NeedForPlanning : 0);
let id3GridNeedKwh = 0, id4GridNeedKwh = 0, carGridPlanReason = 'none';
if (core.ems_enabled && allowGridCharge && wallboxMode !== 'OFF' && wallboxMode !== 'SOLAR' && connectedCarRequiredTotal > 0.5) {
    if (wallboxMode === 'GRID') {
        id3GridNeedKwh = core.id3_connected ? id3Required : 0;
        id4GridNeedKwh = core.id4_connected ? id4Required : 0;
        carGridPlanReason = 'wallbox_grid_mode';
    } else if (wallboxMode === 'AUTO') {
        if (deadlineCars.length > 0) {
            let deadlineGridNeed = connectedDeadlineCarRequired;
            if (hoursToEarliestDeadline !== null && hoursToEarliestDeadline > 18) {
                deadlineGridNeed = Math.max(connectedDeadlineCarRequired - solarKwhBeforeDeadline, 0);
                carGridPlanReason = deadlineGridNeed > 0.5
                    ? 'deadline_deficit_after_forecast'
                    : 'forecast_covers_deadline';
            } else {
                carGridPlanReason = 'car_departure_deadline_soon';
            }
            const split = splitGridDeficitAmongDeadlineCars(deadlineGridNeed, deadlineCars, wallboxPriority);
            id3GridNeedKwh = split.id3;
            id4GridNeedKwh = split.id4;
        } else if ((bad || winter) && connectedNoDeadlineCarRequired > 0.05) {
            id3GridNeedKwh = (core.id3_connected && !id3UseDeparture) ? id3Required : 0;
            id4GridNeedKwh = (core.id4_connected && !id4UseDeparture) ? id4Required : 0;
            carGridPlanReason = bad ? 'bad_day_no_deadline' : 'winter_no_deadline';
        } else carGridPlanReason = 'wait_for_solar_no_deadline';
    }
}
const carGridNeedKwh = id3GridNeedKwh + id4GridNeedKwh;

// AUTO síťové dobíjení domácí baterie je čistá energetická bilance domu.
// SOC target/effective/hard-min jsou limity odložitelných ZÁTĚŽÍ, ne cíl nákupu energie.
//
// Potřebujeme pokrýt zhruba jeden den provozu domu + nastavitelnou energetickou rezervu.
// Proti tomu stojí energie, která už fyzicky je v baterii, a konzervativní část FV forecastu.
const forecastUsableFactor = n(s('input_number.ems_solar_forecast_usable_factor'), 0.8);
const houseDailyConsumptionKwh = n(s('input_number.ems_house_daily_consumption_kwh'), 15);
const houseDailyReserveKwh = n(s('input_number.ems_house_daily_reserve_kwh'), 5);
const houseEnergyRequiredKwh = Math.max(houseDailyConsumptionKwh + houseDailyReserveKwh, 0);

const batteryStoredKwh = Math.max(batteryCapacity * clamp(n(core.battery_soc), 0, 100) / 100, 0);
const batteryRoomToFullKwh = Math.max(batteryCapacity - batteryStoredKwh, 0);

// HOUSE forecast pro AUTO grid charge:
// mimo NT používáme živý forecast. Jakmile běží skutečné HDO=NT, uložíme si
// forecast pro jeden nadcházející solární den a stejný základ držíme přes půlnoc.
// Battery SOC/uložená energie se dál mění, takže deficit normálně klesá s nabíjením.
const planningDate = new Date(now);
const planningHour = planningDate.getHours();

function localDateKey(d) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
}
function nightSolarDayKey(ts) {
    const d = new Date(ts);
    // Večer jde o zítřejší solární den; po půlnoci stále o ten samý den.
    if (d.getHours() >= 12) d.setDate(d.getDate() + 1);
    return localDateKey(d);
}

const liveHouseForecastSource = planningHour >= 18 ? 'tomorrow' : 'remaining_today';
const liveRawHouseForecastKwh = liveHouseForecastSource === 'tomorrow'
    ? Math.max(n(core.forecast_tomorrow), 0)
    : Math.max(n(core.forecast_remaining_today), 0);

const hdoNtActive = String(core.hdo_state || '').toUpperCase() === 'NT';
const currentNightSolarDayKey = nightSolarDayKey(now);
let houseForecastSource = liveHouseForecastSource;
let rawHouseForecastKwh = liveRawHouseForecastKwh;
let houseForecastSnapshotActive = false;

if (hdoNtActive) {
    const snap = plannerMem.house_grid_forecast_snapshot || null;
    if (!snap || snap.solar_day_key !== currentNightSolarDayKey) {
        plannerMem.house_grid_forecast_snapshot = {
            solar_day_key: currentNightSolarDayKey,
            source: liveHouseForecastSource,
            raw_kwh: liveRawHouseForecastKwh,
            created_ts: now
        };
    }
    const activeSnap = plannerMem.house_grid_forecast_snapshot;
    houseForecastSource = `nt_snapshot:${activeSnap.source}`;
    rawHouseForecastKwh = Math.max(n(activeSnap.raw_kwh), 0);
    houseForecastSnapshotActive = true;
}

const usableForecastHouseKwh = rawHouseForecastKwh * forecastUsableFactor;
const houseEnergyAvailableKwh = batteryStoredKwh + usableForecastHouseKwh;
const batteryForecastDeficitKwh = Math.max(houseEnergyRequiredKwh - houseEnergyAvailableKwh, 0);
const batteryGridAutoNeedKwh = Math.min(batteryForecastDeficitKwh, batteryRoomToFullKwh);

// AUTO hysterese: nezačínat kvůli pár stovkám Wh, ale když už se nabíjí,
// dotáhnout deficit prakticky k nule.
const previousBatteryDecision = ems.battery_grid || {};
const previousAutoBatteryRequested =
    !!previousBatteryDecision.charge_enable &&
    String(previousBatteryDecision.reason || '').startsWith('auto_');

const actualBatteryChargingPriority =
    String(s('select.easun_l1_easun_l1_battery_charging_priority', '')).trim().toLowerCase();
const actualOutputPriority =
    String(s('select.easun_l1_easun_l1_output_priority', '')).trim().toLowerCase();
const actualNormalGridConfigured =
    actualBatteryChargingPriority === 'utility priority' &&
    actualOutputPriority === 'utility-pv-battery (uti)';
const actualGridChargeRunning =
    b('switch.sit_menice') && actualNormalGridConfigured;

const batteryAutoAlreadyRunning =
    batteryGridMode === 'AUTO' && (previousAutoBatteryRequested || actualGridChargeRunning);
const batteryAutoStartThresholdKwh = 1.0;
const batteryAutoStopThresholdKwh = 0.2;
const batteryAutoNeedThresholdKwh = batteryAutoAlreadyRunning
    ? batteryAutoStopThresholdKwh
    : batteryAutoStartThresholdKwh;

const currentNtRemainingH = currentNtRemainingHours();
const minNtRemainingForBatteryStartH = n(s('input_number.ems_battery_grid_min_nt_remaining_hours'), 2);
// "Nezačínat pod X hodin NT" je opravdu jen zákaz NOVÉHO STARTU.
// Už běžící potřebné dobíjení tím nesmíme každou minutu ukončit.
const lateNtBatteryStartBlocked =
    batteryGridMode !== 'FORCE' &&
    !batteryAutoAlreadyRunning &&
    currentNtRemainingH !== null &&
    currentNtRemainingH < minNtRemainingForBatteryStartH;

let batteryGridShouldPlan = false;
let batteryGridPlanReason = 'none';
if (!core.ems_enabled || batteryGridMode === 'OFF') {
    batteryGridShouldPlan = false;
    batteryGridPlanReason = !core.ems_enabled ? 'ems_disabled' : 'battery_grid_mode_off';
} else if (batteryGridMode === 'FORCE') {
    batteryGridShouldPlan = allowGridCharge && batteryMissingKwh > 0.1;
    batteryGridPlanReason = batteryGridShouldPlan ? 'force_to_target' : 'force_no_room_to_target';
} else if (!allowGridCharge) {
    batteryGridShouldPlan = false;
    batteryGridPlanReason = 'grid_charge_not_allowed';
} else if (lateNtBatteryStartBlocked) {
    batteryGridShouldPlan = false;
    batteryGridPlanReason = 'late_nt_do_not_start_battery_auto';
} else if (batteryGridAutoNeedKwh > batteryAutoNeedThresholdKwh && batteryRoomToFullKwh > 0.1) {
    batteryGridShouldPlan = true;
    batteryGridPlanReason = batteryAutoAlreadyRunning
        ? 'house_energy_deficit_continue'
        : 'house_energy_deficit_start';
} else {
    batteryGridShouldPlan = false;
    batteryGridPlanReason = batteryForecastDeficitKwh <= batteryAutoStopThresholdKwh
        ? 'house_energy_covered'
        : 'house_deficit_below_start_threshold';
}
const batteryGridNeedKwh = batteryGridShouldPlan
    ? (batteryGridMode === 'FORCE' ? batteryMissingKwh : batteryGridAutoNeedKwh)
    : 0;
const gridNeedTotal = batteryGridNeedKwh + carGridNeedKwh;
const maxGridPurchaseKw = 11;
const departurePlan = { cars: {
    id3: { connected:!!core.id3_connected, needs_target:id3NeedsTarget, required_kwh:id3NeedForPlanning, use_departure:id3UseDeparture, departure_ts:id3Departure },
    id4: { connected:!!core.id4_connected, needs_target:id4NeedsTarget, required_kwh:id4NeedForPlanning, use_departure:id4UseDeparture, departure_ts:id4Departure }
} };
const gridPurchasePlan = buildHdoSpreadPlan({id3:id3GridNeedKwh, id4:id4GridNeedKwh, battery:batteryGridNeedKwh}, departurePlan, maxGridPurchaseKw);
const id3GridActive = loadActive(gridPurchasePlan.loads?.id3, now);
const id4GridActive = loadActive(gridPurchasePlan.loads?.id4, now);
const batteryGridActive = loadActive(gridPurchasePlan.loads?.battery, now);
allowCarGrid = !!(core.ems_enabled && allowGridCharge && (id3GridActive || id4GridActive));
const allowBatteryGrid = !!(core.ems_enabled && allowGridCharge && batteryGridActive);

ems.plan = {
    ts: now,
    battery: {
        capacity_kwh:batteryCapacity,
        hard_min_soc:hardMinSoc,
        target_soc:n(core.target_soc),
        effective_min_soc:n(core.effective_min_soc),
        // Tyto dvě položky jsou už jen load-target diagnostika, NE AUTO grid target.
        missing_soc:round1(batteryMissingSoc),
        missing_kwh:round1(batteryMissingKwh),
        grid_need_kwh:round1(batteryGridNeedKwh),
        grid_plan_reason:batteryGridPlanReason,
        forecast_usable_factor:round1(forecastUsableFactor),
        stored_kwh:round1(batteryStoredKwh),
        room_to_full_kwh:round1(batteryRoomToFullKwh),
        house_daily_consumption_kwh:round1(houseDailyConsumptionKwh),
        house_daily_reserve_kwh:round1(houseDailyReserveKwh),
        house_energy_required_kwh:round1(houseEnergyRequiredKwh),
        house_forecast_source:houseForecastSource,
        house_forecast_snapshot_active:houseForecastSnapshotActive,
        house_forecast_solar_day:houseForecastSnapshotActive ? currentNightSolarDayKey : null,
        house_forecast_raw_kwh:round1(rawHouseForecastKwh),
        house_forecast_snapshot_created_ts:houseForecastSnapshotActive
            ? Number(plannerMem.house_grid_forecast_snapshot?.created_ts || 0)
            : null,
        usable_forecast_house_kwh:round1(usableForecastHouseKwh),
        house_energy_available_kwh:round1(houseEnergyAvailableKwh),
        forecast_deficit_kwh:round1(batteryForecastDeficitKwh),
        auto_grid_running:batteryAutoAlreadyRunning,
        auto_start_threshold_kwh:batteryAutoStartThresholdKwh,
        auto_stop_threshold_kwh:batteryAutoStopThresholdKwh,
        nt_remaining_h:currentNtRemainingH===null?null:round1(currentNtRemainingH),
        late_nt_blocked:lateNtBatteryStartBlocked,
        load_locked:!!core.battery_load_locked,
        unlock_soc:n(core.battery_load_unlock_soc)
    },
