} : {l1:null,l2:null,l3:null};
const basePhaseMaxW = inverterPhaseSensorsValid ? Math.max(...Object.values(basePhaseWithoutSolarWallbox)) : null;
const inverterSafeWallboxTotalA = inverterPhaseSensorsValid
    ? wallboxStepAtOrBelowOrZero((inverterSafePhaseLimitW - basePhaseMaxW) / 230)
    : null;

let inverterPhaseGuard = {
    active: false,
    reason: 'ok',
    sensors_valid: inverterPhaseSensorsValid,
    phase_limit_w: inverterPhaseLimitW,
    safety_margin_w: inverterSafetyMarginW,
    safe_phase_limit_w: inverterSafePhaseLimitW,
    phase_actual_w: inverterPhaseActual,
    phase_base_without_solar_wallbox_w: basePhaseWithoutSolarWallbox,
    actual_solar_wallbox_a: actualSolarWallboxA,
    requested_solar_wallbox_a: requestedSolarWallboxA,
    safe_wallbox_total_a: inverterSafeWallboxTotalA,
    target_before: {
        enable: {...wallboxEnableTarget},
        current: {...wallboxCurrentTarget}
    }
};

// Když mají být wallboxy cílově na SOLAR straně, clampni celý jejich proudový rozpočet.
if (String(wallboxEnableTarget.source || 'SOLAR').toUpperCase() === 'SOLAR' && targetAnyOn(wallboxEnableTarget)) {
    if (!inverterPhaseSensorsValid) {
        // Při neznámých fázích nezvyšuj výkon ani nezapínej nový SOLAR wallbox.
        const newEnableRequested =
            (!actualWallboxEnable.id3_enable && wallboxEnableTarget.id3_enable) ||
            (!actualWallboxEnable.id4_enable && wallboxEnableTarget.id4_enable) ||
            String(actualWallboxEnable.source || 'SOLAR').toUpperCase() !== 'SOLAR';
        const increaseRequested = requestedSolarWallboxA > actualSolarWallboxA;
        if (newEnableRequested || increaseRequested) {
            inverterPhaseGuard.active = true;
            inverterPhaseGuard.reason = 'phase_sensor_unavailable_block_increase';
            if (String(actualWallboxEnable.source || 'SOLAR').toUpperCase() === 'SOLAR') {
                wallboxEnableTarget = {...actualWallboxEnable};
                wallboxCurrentTarget = {...actualWallboxCurrent};
            } else {
                wallboxEnableTarget = {...safetyWallboxEnableTarget};
                wallboxCurrentTarget = {...safetyWallboxCurrentTarget};
            }
        }
    } else if (requestedSolarWallboxA > inverterSafeWallboxTotalA) {
        inverterPhaseGuard.active = true;
        inverterPhaseGuard.reason = inverterSafeWallboxTotalA < 6
            ? 'inverter_phase_no_6a_capacity'
            : 'inverter_phase_target_clamped';
        const clamped = clampSolarTargetsToTotalBudget(
            wallboxEnableTarget,
            wallboxCurrentTarget,
            inverterSafeWallboxTotalA,
            actualWallboxEnable,
            actualWallboxCurrent
        );
        wallboxEnableTarget = clamped.enable;
        wallboxCurrentTarget = clamped.current;
    }
}

// Pokud je wallbox TEĎ fyzicky na SOLAR straně, nesmí se jeho proud zvýšit před přepnutím
// zdroje na GRID. To zavírá i 2s okno mezi current service a enable/source service.
if (
    String(actualWallboxEnable.source || 'SOLAR').toUpperCase() === 'SOLAR' &&
    actualSolarWallboxA > 0
) {
    const targetedWhileStillSolarA =
        (actualWallboxEnable.id3_enable ? Math.max(roundCurrent(wallboxCurrentTarget.id3_current), 0) : 0) +
        (actualWallboxEnable.id4_enable ? Math.max(roundCurrent(wallboxCurrentTarget.id4_current), 0) : 0);
    if (
        String(wallboxEnableTarget.source || 'SOLAR').toUpperCase() === 'GRID' &&
        targetedWhileStillSolarA > actualSolarWallboxA
    ) {
        inverterPhaseGuard.active = true;
        inverterPhaseGuard.reason = 'wait_for_grid_transfer_before_current_increase';
        wallboxCurrentTarget = {...actualWallboxCurrent};
    }
}

inverterPhaseGuard.target_after = {
    enable: {...wallboxEnableTarget},
    current: {...wallboxCurrentTarget}
};
changed.inverter_phase_guard = !!inverterPhaseGuard.active;

const wallboxControlAllowed =
    wallboxLive ||
    balanceBlocksWallbox ||
    wallboxBatteryProtectionActive ||
    rawWallboxWantsGrid ||
    forceSolarWallboxActive;

const batteryTarget = batteryLive ? rawBatteryTarget : { charge_enable: false, current_a: 0 };

const wallboxRecentChange = Date.now() - (ems.dispatcher.last.wallbox_action_ts || 0) < BOILER_LOCKOUT_AFTER_WALLBOX_MS;
const wallboxEnablePending = !!ems.dispatcher.pending.wallbox_enable;
const wallboxActiveOrRequested = targetAnyOn(wallboxEnableTarget) || actualWallboxEnable.id3_enable || actualWallboxEnable.id4_enable || wallboxEnablePending;

// FORCE_SOLAR boiler is a deliberate battery load and bypasses ordinary wallbox/boiler
// priority lockout. It is still blocked by AC-in or the shared voltage floor.
const forceBoilerOffForWallbox =
    !forceSolarBoilerActive && (wallboxActiveOrRequested || wallboxRecentChange);
const forceSolarBoilerBlocked = forceSolarBoilerActive && !forceSolarGuardOk;
let boilerTarget = (!boilerLive || balanceBlocksBoiler || forceBoilerOffForWallbox || forceSolarBoilerBlocked)
    ? { bottom_t1: false, bottom_t2: false, pergola_t1: false, pergola_t2: false }
    : rawBoilerTarget;

// Stejný hard limit platí i pro bojlery. Neznáme zde přesné fázové rozložení
// jednotlivých spirál, proto je ochrana záměrně konzervativní: nový příkon bojleru
// počítá v nejhorším případě do právě nejzatíženější fáze.
const boilerPowerW = t =>
    (t?.bottom_t1 ? 1000 : 0) +
    (t?.bottom_t2 ? 1000 : 0) +
    (t?.pergola_t1 ? 800 : 0) +
    (t?.pergola_t2 ? 800 : 0);
const actualBoilerPowerW = boilerPowerW(actualBoiler);
const requestedBoilerPowerW = boilerPowerW(boilerTarget);
const boilerIncreaseW = Math.max(requestedBoilerPowerW - actualBoilerPowerW, 0);
const guardedSolarWallboxA = totalWallboxCurrentA(wallboxEnableTarget, wallboxCurrentTarget);
const positiveWallboxIncreaseW = Math.max(guardedSolarWallboxA - actualSolarWallboxA, 0) * 230;
const conservativeProjectedPhaseW = inverterPhaseSensorsValid
    ? actualPhaseMaxW + positiveWallboxIncreaseW + boilerIncreaseW
    : null;
let boilerPhaseGuardReason = 'ok';

if (inverterPhaseSensorsValid) {
    if (actualPhaseMaxW > inverterSafePhaseLimitW && actualBoilerPowerW > 0) {
        boilerTarget = { bottom_t1:false, bottom_t2:false, pergola_t1:false, pergola_t2:false };
        boilerPhaseGuardReason = 'inverter_phase_over_safe_limit_shed_boiler';
        inverterPhaseGuard.active = true;
    } else if (boilerIncreaseW > 0 && conservativeProjectedPhaseW > inverterSafePhaseLimitW) {
        // Nepřidávej žádný nový boiler stage v cyklu, který by mohl sežrat rezervu měniče.
        // Stávající už zapnuté stupně ponech; pokud je fáze opravdu za limitem,
        // předchozí větev je shodí.
        boilerTarget = {...actualBoiler};
        boilerPhaseGuardReason = 'inverter_phase_block_boiler_increase';
        inverterPhaseGuard.active = true;
    }
} else if (boilerIncreaseW > 0) {
    // Bez platných fázových měření nepouštěj nový automatický/force výkon na měnič.
    boilerTarget = {...actualBoiler};
    boilerPhaseGuardReason = 'phase_sensor_unavailable_block_boiler_increase';
    inverterPhaseGuard.active = true;
}

inverterPhaseGuard.boiler = {
    reason: boilerPhaseGuardReason,
    actual_power_w: actualBoilerPowerW,
    requested_power_w: requestedBoilerPowerW,
    increase_w: boilerIncreaseW,
    conservative_projected_phase_w: conservativeProjectedPhaseW,
    target_after: {...boilerTarget}
};
if (boilerPhaseGuardReason !== 'ok') {
    inverterPhaseGuard.reason = inverterPhaseGuard.reason === 'ok'
        ? boilerPhaseGuardReason
        : inverterPhaseGuard.reason + '+' + boilerPhaseGuardReason;
    changed.inverter_phase_guard = true;
}

function handleVerifiedApply(key, target, actual, sameFn, makeMsgFn, title, verifyDelayMs, liveAllowed = true, opts = {}) {
    let pending = ems.dispatcher.pending[key];
    const blockedUntil = ems.dispatcher.blocked_until[key] || 0;
    const maxRetries = MAX_RETRIES[key] ?? 2;

    if (!liveAllowed) {
        delete ems.dispatcher.pending[key];
        delete ems.dispatcher.blocked_until[key];
        return null;
    }

    if (pending && opts.forceOverride && !sameFn(pending.target, target)) {
        pending = null;
        delete ems.dispatcher.pending[key];
        changed.wallbox_safety_override = key === 'wallbox_enable';
    }

    if (pending) {
        if (sameFn(actual, pending.target)) {
            ems.dispatcher.last[key] = stableString(pending.target);
            delete ems.dispatcher.pending[key];
            delete ems.dispatcher.blocked_until[key];
            delete ems.dispatcher.failed_target_notified[key];
            changed[key + '_verified'] = true;
            return null;
        }
        if (!shouldVerify(pending, verifyDelayMs)) return null;
        if ((pending.retries || 0) < maxRetries) {
            const retryTarget = pending.target;
            ems.dispatcher.pending[key] = makePending(retryTarget, (pending.retries || 0) + 1);
            changed[key + '_retry'] = true;
            return makeMsgFn(retryTarget);
        }
        delete ems.dispatcher.pending[key];
        ems.dispatcher.blocked_until[key] = Date.now() + ERROR_COOLDOWN_MS;

        // Wallbox enable failure is noisy during car sleep / finishing; do not spam phone.
        // Pro ostatní výstupy: jedna notifikace pro jeden nezměněný failed target.
        if (key !== 'wallbox_enable') {
            const failedSignature = stableString(pending.target);
            if (ems.dispatcher.failed_target_notified[key] !== failedSignature) {
                requestError(
                    'EMS: akce se neprovedla',
                    `${title} se nepodařilo aplikovat ani po ${maxRetries} opakování. Target: ${stableString(pending.target)} Actual: ${stableString(actual)}`
                );
                ems.dispatcher.failed_target_notified[key] = failedSignature;
            }
        }
        return null;
    }

    if (sameFn(actual, target)) {
        ems.dispatcher.last[key] = stableString(target);
        delete ems.dispatcher.blocked_until[key];
        delete ems.dispatcher.failed_target_notified[key];
        return null;
    }
    if (Date.now() < blockedUntil) return null;

    const newTargetSignature = stableString(target);
    if (
        ems.dispatcher.failed_target_notified[key] &&
        ems.dispatcher.failed_target_notified[key] !== newTargetSignature
    ) {
        delete ems.dispatcher.failed_target_notified[key];
    }
    ems.dispatcher.pending[key] = makePending(target, 0);
    changed[key] = true;
    return makeMsgFn(target);
}

// 1) Enable/disable and source switch only. This path never changes current.
wallboxEnableMsg = handleVerifiedApply(
    'wallbox_enable',
    wallboxEnableTarget,
    actualWallboxEnable,
    sameEnable,
    target => ({ payload: target }),
    'Wallbox enable',
    VERIFY_DELAY.wallbox_enable,
    wallboxControlAllowed,
    { forceOverride: wallboxBatteryProtectionActive || rawWallboxWantsGrid || forceSolarWallboxActive || inverterPhaseGuard.active }
);

// 2) Current-only path. This must never call turn_on/turn_off.
// If we are about to enable a wallbox, set current first. The enable service node is delayed by 2 s.
if (
    wallboxControlAllowed &&
    (!wallboxBatteryProtectionActive || rawWallboxWantsGrid || forceSolarWallboxPermitted) &&
    targetAnyOn(wallboxEnableTarget)
) {
    const currentDiffers = !sameCurrent(actualWallboxCurrent, wallboxCurrentTarget);
    const enableChanging = !!wallboxEnableMsg;
    const lastCurrentTs = ems.dispatcher.last.wallbox_current_action_ts || 0;
    const currentUpCooldownOk = (Date.now() - lastCurrentTs) >= WALLBOX_CURRENT_UP_COOLDOWN_MS;

    // Snížení proudu je ochranná/stabilizační akce a nesmí čekat na cooldown.
    // Zvýšení už předfiltroval wallbox regulátor minutovou stabilitou, tady jen bráníme
    // zbytečně rychlému opakování service callů.
    const enabledId3 = !!wallboxEnableTarget.id3_enable;
    const enabledId4 = !!wallboxEnableTarget.id4_enable;
    const requestedDown =
        (enabledId3 && roundCurrent(wallboxCurrentTarget.id3_current) < roundCurrent(actualWallboxCurrent.id3_current)) ||
        (enabledId4 && roundCurrent(wallboxCurrentTarget.id4_current) < roundCurrent(actualWallboxCurrent.id4_current));

    if (currentDiffers && (enableChanging || requestedDown || currentUpCooldownOk)) {
        wallboxCurrentMsg = { payload: wallboxCurrentTarget };
        ems.dispatcher.last.wallbox_current_action_ts = Date.now();
        ems.dispatcher.last.wallbox_current = stableString(wallboxCurrentTarget);
        changed.wallbox_current = true;
    } else if (currentDiffers) {
        changed.wallbox_current_skipped_cooldown = true;
    }
}

if (wallboxEnableMsg || wallboxCurrentMsg) {
    ems.dispatcher.last.wallbox_action_ts = Date.now();
}


const emergencyBatteryOwnerActive = !!ems.safety?.emergency?.active;

// Battery task cleanup: after Force/Balance completes, always call stop script once.
// During emergency charging Safety Manager owns the inverter charge mode.
const cleanupRequest = ems.tasks?.cleanup_request || ems.tasks?.battery_task?.cleanup_request || null;
const cleanupId = cleanupRequest?.id || cleanupRequest?.task_key || null;
if (!emergencyBatteryOwnerActive && cleanupId && ems.dispatcher.last.battery_cleanup_id !== cleanupId) {
    batteryStopMsg = { payload: { cleanup: true, reason: cleanupRequest.reason || 'battery_task_completed' } };
    changed.battery_stop = true;
    changed.battery_cleanup = true;
    ems.dispatcher.last.battery_cleanup_id = cleanupId;
    if (ems.memory?.tasks?.battery_completion?.cleanup_request) {
        ems.memory.tasks.battery_completion.cleanup_ack_ts = Date.now();
    }
}

if (emergencyBatteryOwnerActive) {
    delete ems.dispatcher.pending.battery;
    delete ems.dispatcher.blocked_until.battery;
}

const batteryMsg = (!batteryStopMsg && !emergencyBatteryOwnerActive) ? handleVerifiedApply(
    'battery',
    batteryTarget,
    actualBattery,
    sameBattery,
    target => ({ payload: target }),
    'Battery grid charge',
    VERIFY_DELAY.battery,
    true
) : null;
if (batteryMsg) {
    if (batteryMsg.payload.charge_enable) {
        batteryStartMsg = { payload: { current_a: batteryMsg.payload.current_a } };
        changed.battery_start = true;
    } else {
        batteryStopMsg = { payload: {} };
        changed.battery_stop = true;
    }
}

boilerMsg = handleVerifiedApply(
    'boiler',
    boilerTarget,
    actualBoiler,
    sameBoiler,
    target => ({ payload: target }),
    'Bojlery',
    VERIFY_DELAY.boiler,
    true
);
if (boilerMsg) changed.boiler = true;

const woodNotificationKey = boiler.ask_notification ? boiler.notification_reason : null;
if (core.ems_live_notifications && woodNotificationKey && ems.dispatcher.last.wood_notification !== woodNotificationKey) {
    ems.dispatcher.last.wood_notification = woodNotificationKey;
    notifyWoodMsg = { payload: {} };
    changed.notify_wood = true;
}
if (!woodNotificationKey) ems.dispatcher.last.wood_notification = null;

const priorityNotificationKey = wallbox.ask_priority ? wallbox.notification_reason : null;
if (core.ems_live_notifications && priorityNotificationKey && ems.dispatcher.last.wallbox_priority_notification !== priorityNotificationKey) {
    ems.dispatcher.last.wallbox_priority_notification = priorityNotificationKey;
    notifyPriorityMsg = { payload: {} };
    changed.notify_priority = true;
}
if (!priorityNotificationKey) ems.dispatcher.last.wallbox_priority_notification = null;

// Jednorázová notifikace o selhání FORCE_SOLAR. Task Manager drží událost
// v global.ems.memory až do potvrzení dispatcherem, takže se neztratí při rychlém
// automatickém přepnutí force helperu na OFF.
const forceSolarFailure = ems.memory?.tasks?.force_solar?.notification || null;
if (!errorMsg && forceSolarFailure && !forceSolarFailure.ack_ts) {
    requestError(
        forceSolarFailure.title || 'EMS: FORCE_SOLAR chyba',
        forceSolarFailure.message || 'FORCE_SOLAR byl ukončen bezpečnostní ochranou.'
    );
    forceSolarFailure.ack_ts = Date.now();
}

ems.dispatcher.last_action =
    wallboxCurrentMsg ? 'wallbox_current_apply' :
    wallboxEnableMsg ? 'wallbox_enable_apply' :
    batteryStartMsg ? 'battery_grid_start' :
    changed.battery_cleanup ? 'battery_task_cleanup' :
    batteryStopMsg ? 'battery_grid_stop' :
    boilerMsg ? 'boiler_apply' :
    notifyWoodMsg ? 'notify_wood_plan' :
    notifyPriorityMsg ? 'notify_wallbox_priority' :
    errorMsg ? 'notify_error' :
    changed.wallbox_enable_verified ? 'wallbox_enable_verified' :
    changed.wallbox_enable_retry ? 'wallbox_enable_retry' :
    changed.wallbox_current_skipped_cooldown ? 'wallbox_current_cooldown' :
    changed.wallbox_safety_override ? 'wallbox_safety_override' :
    changed.inverter_phase_guard ? 'inverter_phase_guard' :
    changed.battery_verified ? 'battery_verified' :
    changed.battery_retry ? 'battery_retry' :
    changed.boiler_verified ? 'boiler_verified' :
    changed.boiler_retry ? 'boiler_retry' :
    'idle';

ems.dispatcher.actual_wallbox_enable = actualWallboxEnable;
ems.dispatcher.actual_wallbox_current = actualWallboxCurrent;
ems.dispatcher.wallbox_enable_target = wallboxEnableTarget;
ems.dispatcher.wallbox_current_target = wallboxCurrentTarget;

ems.dispatcher.last_change = Date.now();
global.set('ems', ems);

const debugPayload = {
    ts: Date.now(),
    wallboxLive,
    batteryLive,
    boilerLive,
    wallboxBatteryProtectionActive,
    rawWallboxWantsGrid,
    wallboxControlAllowed,
    inverterPhaseGuard,
    forceSolarWallboxActive,
    forceSolarBoilerActive,
    forceSolarAnyActive,
    balanceLoadLockActive,
    balanceBlocksWallbox,
    balanceBlocksBoiler,
    forceWallboxTaskActive,
    forceBoilerTaskActive,
    explicitForceBoilerMode,
    forceSolarAcInOn,
    forceSolarVoltageV,
    forceSolarVoltageValid,
    forceSolarConnectBelowV,
    forceSolarFloorV,
    forceSolarGuardOk,
    forceSolarWallboxPermitted,
    forceSolarBoilerPermitted,
    forceSolarWallboxBlocked,
    forceSolarBoilerBlocked,
    forceBoilerOffForWallbox,
    wallboxRecentChange,
    wallboxEnablePending,
    rawWallboxEnableTarget,
    wallboxEnableTarget,
    actualWallboxEnable,
    rawWallboxCurrentTarget,
    wallboxCurrentTarget,
    actualWallboxCurrent,
    rawBatteryTarget,
    batteryTarget,
    actualBattery,
    batteryChargeOwner: emergencyBatteryOwnerActive
        ? 'EMERGENCY_SAFETY'
        : (batteryTarget.charge_enable ? 'EMS_GRID' : 'NONE'),
    rawBoilerTarget,
    boilerTarget,
    actualBoiler,
    pending: ems.dispatcher.pending,
    blocked_until: ems.dispatcher.blocked_until,
    changed,
    last: ems.dispatcher.last,
    last_action: ems.dispatcher.last_action
};

const debug = { topic: 'ems/dispatcher', payload: debugPayload };
const anyAction = wallboxCurrentMsg || wallboxEnableMsg || batteryStartMsg || batteryStopMsg || boilerMsg || notifyWoodMsg || notifyPriorityMsg || errorMsg;
const hasPending = Object.keys(ems.dispatcher.pending).length > 0;
node.status({
    fill: anyAction ? 'green' : (hasPending ? 'yellow' : 'grey'),
    shape: anyAction ? 'dot' : 'ring',
    text: anyAction ? ems.dispatcher.last_action : (hasPending ? 'pending verify' : 'idle')
});

return [
    wallboxCurrentMsg,
    wallboxEnableMsg,
    batteryStartMsg,
    batteryStopMsg,
    boilerMsg,
    notifyWoodMsg,
    notifyPriorityMsg,
    errorMsg,
    debug
];

function n(v, def = 0) {
    const x = Number(v);
