const ha = global.get('homeassistant');
const states = ha?.homeAssistant?.states || {};
function s(id, def = undefined) { return states[id]?.state ?? def; }
function b(id) { return states[id]?.state === 'on'; }
function raw(id) { return states[id]?.state; }
