        hold_hysteresis:'Drží stav podle hystereze', manager_disabled_keep_current:'Správce vypnutý, drží aktuální stav',
        emergency_battery_voltage_critical:'Nouzově připojuje síť kvůli baterii', battery_grid_charge_requested:'EMS požaduje dobíjení baterie',
        battery_force_task_grid_requested:'Force úkol požaduje síť', force_on:'Ručně trvale zapnuto', force_off:'Ručně vypnuto',
        force_off_overridden_low_voltage:'Ruční vypnutí přebito nízkým napětím', battery_voltage_below_connect_threshold:'Napětí pod prahem pro připnutí sítě',
