const core = ems.core || {};
const normalBatteryGridActive = !!ems.battery_grid?.charge_enable;
const taskBatteryGridActive = !!ems.tasks?.battery_primary?.active && !!ems.tasks?.battery_primary?.grid_allowed;
const forceSolarAnyActive = !!(
